include  <p>using namespace sentinel::sdk;</p> <p>static SentinelDissectorResult custom_dissect(const SentinelRawPacket* raw_pkt) {     if (!raw_pkt || !raw_pkt-&gt;data || raw_pkt-&gt;length &lt; 8) {         return VerdictBuilder::Pass();     }</p> <pre><code>// Constant-time inspect bytes
